const header = insomnia.response.headers.get('authorization');
const token = typeof header === 'string' ? header : header && header.value;
if (token) {
  insomnia.environment.set('csrf_token', token);
  console.log('Saved CSRF token');
} else {
  console.log('No authorization header in the response - sign-in failed');
}

