function uuidv7() {
  const r = () => Math.floor(Math.random() * 16).toString(16);
  let s = Date.now().toString(16).padStart(12, '0') + '7';
  for (let i = 0; i < 3; i++) s += r();
  s += (8 + Math.floor(Math.random() * 4)).toString(16);
  for (let i = 0; i < 15; i++) s += r();
  return s.slice(0, 8) + '-' + s.slice(8, 12) + '-' + s.slice(12, 16) + '-' + s.slice(16, 20) + '-' + s.slice(20);
}
insomnia.environment.set('trip_id', uuidv7());

