if (insomnia.response.code >= 200 && insomnia.response.code < 300) {
  const body = insomnia.response.json();
  if (body && body.token !== undefined) { insomnia.environment.set('invite_token', body.token); console.log('Saved invite_token'); }
} else {
  console.log('Request failed with status ' + insomnia.response.code + ' - nothing saved');
}
